-- Phase L follow-up: hardened cron parser semantics used by the durable scheduler.
create or replace function public.cron_field_matches(p_field text,p_value integer,p_min integer,p_max integer) returns boolean language plpgsql immutable as $$ declare part text; base text; step integer; a integer; b integer; v integer; begin if p_field is null or p_field='' or p_value<p_min or p_value>p_max then return false; end if; foreach part in array string_to_array(trim(p_field),',') loop if part='' then continue; end if; step:=1; if position('/' in part)>0 then if regexp_count(part,'/')<>1 then return false; end if; base:=split_part(part,'/',1); if split_part(part,'/',2) !~ '^[0-9]+$' then return false; end if; step:=split_part(part,'/',2)::integer; if step<1 then return false; end if; else base:=part; end if; if base='*' then a:=p_min; b:=p_max; elsif base~'^[0-9]+$' then a:=base::integer; b:=a; elsif base~'^[0-9]+-[0-9]+$' then a:=split_part(base,'-',1)::integer; b:=split_part(base,'-',2)::integer; else return false; end if; if p_min=1 and p_max=7 and a=0 then a:=7; if b=0 then b:=7; end if; end if; if a<p_min or b>p_max or a>b then return false; end if; for v in a..b loop if v=p_value and mod(v-a,step)=0 then return true; end if; end loop; end loop; return false; exception when others then return false; end; $$;
create or replace function public.next_cron_run(p_expr text,p_after timestamptz,p_timezone text default 'UTC') returns timestamptz language plpgsql immutable as $$ declare f text[]; cur timestamptz; local timestamp; i integer; begin if p_expr is null or p_after is null then return null; end if; begin perform 1 from pg_timezone_names where name=p_timezone; if not found then return null; end if; exception when others then return null; end; f:=regexp_split_to_array(trim(p_expr),'[[:space:]]+'); if array_length(f,1)<>5 then return null; end if; cur:=date_trunc('minute',p_after)+interval '1 minute'; for i in 0..527039 loop local:=cur at time zone p_timezone; if public.cron_field_matches(f[1],extract(minute from local)::integer,0,59) and public.cron_field_matches(f[2],extract(hour from local)::integer,0,23) and public.cron_field_matches(f[3],extract(day from local)::integer,1,31) and public.cron_field_matches(f[4],extract(month from local)::integer,1,12) and public.cron_field_matches(f[5],extract(isodow from local)::integer,1,7) then return cur; end if; cur:=cur+interval '1 minute'; end loop; return null; end; $$;
revoke all on function public.next_cron_run(text,timestamptz,text) from public,anon,authenticated;
revoke all on function public.cron_field_matches(text,integer,integer,integer) from public,anon,authenticated;
